package school.magiccodex.paper;
import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import school.magiccodex.protocol.GeneralPresetProtocol;import school.magiccodex.protocol.GeneralPresetModeProtocol;
class GeneralPresetModePolicyTest{
 @Test void everyActualCycleTransitionUsesUnchangedCooldownGate(){for(int[] pair:new int[][]{{1,2},{2,3},{3,1}}){var cds=new HashMap<String,Long>();cds.put("hidden_other_preset",5000L);var before=Map.copyOf(cds);assertEquals(1,GeneralPresetModePolicy.status(pair[0],pair[1],true,false,false,cds,100));assertEquals(before,cds);assertEquals(0,GeneralPresetModePolicy.status(pair[0],pair[1],true,false,false,cds,5000));assertEquals(before,cds);}}
 @Test void offCannotBypassCombatCastingOrUnavailableState(){for(int[] pair:new int[][]{{1,2},{2,3},{3,1}}){assertEquals(2,GeneralPresetModePolicy.status(pair[0],pair[1],true,true,false,Map.of(),0));assertEquals(1,GeneralPresetModePolicy.status(pair[0],pair[1],true,false,true,Map.of(),0));assertEquals(3,GeneralPresetModePolicy.status(pair[0],pair[1],false,false,false,Map.of(),0));}assertEquals(3,GeneralPresetModePolicy.status(1,4,true,false,false,Map.of(),0));}
 @Test void legacyProtocolRemainsOneTwoOnlyAndV2CanRoundTripOff(){assertThrows(IllegalArgumentException.class,()->GeneralPresetProtocol.encode(new GeneralPresetProtocol.Request(1,3)));for(int i=0;i<=3;i++){var q=new GeneralPresetModeProtocol.Request(1,i);assertEquals(q,GeneralPresetModeProtocol.request(GeneralPresetModeProtocol.encode(q)));}for(int i=1;i<=3;i++){var q=new GeneralPresetModeProtocol.Response(1,i,0);assertEquals(q,GeneralPresetModeProtocol.response(GeneralPresetModeProtocol.encode(q)));}assertThrows(IllegalArgumentException.class,()->GeneralPresetModeProtocol.request(GeneralPresetProtocol.encode(new GeneralPresetProtocol.Request(1,1))));assertThrows(IllegalArgumentException.class,()->GeneralPresetModeProtocol.request(new byte[99]));}
}
